// Package bits extracts and inserts bit fields of CAN payloads in the two
// layouts of CAN databases. It is the small runtime that code generated by
// package codegen imports, and the core of the candb signal codec.
//
// Little-endian (Intel) fields are numbered as in DBC: bit b is bit b%8
// of byte b/8, and a field of n bits starting at bit s holds the payload,
// read as a little-endian integer, shifted right by s.
//
// Big-endian (Motorola) fields use a linear index counted from the most
// significant bit of byte 0 (index 0) to the least significant bit of the
// last byte: the field holds the payload, read as a big-endian integer,
// at indexes msb..msb+n-1. [MotorolaStart] converts a DBC start bit (the
// position of the field's most significant bit in Intel numbering) to it.
package bits

// MotorolaStart converts the DBC start bit of a big-endian signal to the
// linear index of its most significant bit.
func MotorolaStart(dbcStart int) int { return dbcStart/8*8 + 7 - dbcStart%8 }

// MotorolaDBCStart is the inverse of [MotorolaStart].
func MotorolaDBCStart(linear int) int { return linear/8*8 + 7 - linear%8 }

func mask(n int) uint64 {
	if n >= 64 {
		return ^uint64(0)
	}
	return 1<<uint(n) - 1
}

// ExtractLE returns the n-bit (1..64) little-endian field at start.
// The caller guarantees start+n <= 8*len(d).
func ExtractLE(d []byte, start, n int) uint64 {
	var v uint64
	shift := 0
	pos := start
	for n > 0 {
		bit := pos & 7
		k := 8 - bit
		if k > n {
			k = n
		}
		v |= (uint64(d[pos>>3]) >> uint(bit) & mask(k)) << uint(shift)
		shift += k
		pos += k
		n -= k
	}
	return v
}

// ExtractBE returns the n-bit (1..64) big-endian field whose most
// significant bit has the linear index msb. The caller guarantees
// msb+n <= 8*len(d).
func ExtractBE(d []byte, msb, n int) uint64 {
	var v uint64
	pos := msb
	for n > 0 {
		off := pos & 7 // from the byte's most significant bit
		k := 8 - off
		if k > n {
			k = n
		}
		v = v<<uint(k) | uint64(d[pos>>3])>>uint(8-off-k)&mask(k)
		pos += k
		n -= k
	}
	return v
}

// InsertLE writes the low n bits of v as the little-endian field at
// start, leaving the other bits of d unchanged.
func InsertLE(d []byte, start, n int, v uint64) {
	pos := start
	for n > 0 {
		bit := pos & 7
		k := 8 - bit
		if k > n {
			k = n
		}
		m := byte(mask(k) << uint(bit))
		d[pos>>3] = d[pos>>3]&^m | byte(v<<uint(bit))&m
		v >>= uint(k)
		pos += k
		n -= k
	}
}

// InsertBE writes the low n bits of v as the big-endian field whose most
// significant bit has the linear index msb, leaving the other bits of d
// unchanged.
func InsertBE(d []byte, msb, n int, v uint64) {
	// Fill from the least significant end: the field's last linear index.
	pos := msb + n - 1
	for n > 0 {
		off := pos & 7      // index of this bit from the byte's MSB
		lsbShift := 7 - off // its shift from the byte's LSB
		k := off + 1        // bits available in this byte towards the MSB
		if k > n {
			k = n
		}
		m := byte(mask(k) << uint(lsbShift))
		d[pos>>3] = d[pos>>3]&^m | byte(v<<uint(lsbShift))&m
		v >>= uint(k)
		pos -= k
		n -= k
	}
}

// SignExtend interprets the low n bits of v as a two's complement number.
func SignExtend(v uint64, n int) int64 {
	if n >= 64 {
		return int64(v)
	}
	shift := uint(64 - n)
	return int64(v<<shift) >> shift
}

// FitsUnsigned reports whether v fits in n bits.
func FitsUnsigned(v uint64, n int) bool { return n >= 64 || v>>uint(n) == 0 }

// FitsSigned reports whether v fits in n bits as two's complement.
func FitsSigned(v int64, n int) bool {
	if n >= 64 {
		return true
	}
	min := -(int64(1) << uint(n-1))
	return v >= min && v <= -min-1
}

// Truncate keeps the low n bits of v.
func Truncate(v uint64, n int) uint64 { return v & mask(n) }
